/// Reports health state of the specified Service Fabric replica. The report must contain the information about the source of the health report and property on which it is reported. The report is sent to a Service Fabric gateway Replica, which forwards to the health store. The report may be accepted by the gateway, but rejected by the health store after extra validation. For example, the health store may reject the report because of an invalid parameter, like a stale sequence number. To see whether the report was applied in the health store, run GetReplicaHealth and check that the report appears in the HealthEvents section.
pub async fn report_replica_health(configuration: &configuration::Configuration, api_version: &str, partition_id: &str, replica_id: &str, service_kind: &str, health_information: models::HealthInformation, immediate: Option<bool>, timeout: Option<i64>) -> Result<(), Error<ReportReplicaHealthError>> {
    // add a prefix to parameters to efficiently prevent name collisions
    let p_query_api_version = api_version;
    let p_path_partition_id = partition_id;
    let p_path_replica_id = replica_id;
    let p_query_service_kind = service_kind;
    let p_body_health_information = health_information;
    let p_query_immediate = immediate;
    let p_query_timeout = timeout;

    let uri_str = format!("{}/Partitions/{partitionId}/$/GetReplicas/{replicaId}/$/ReportHealth", configuration.base_path, partitionId=crate::apis::urlencode(p_path_partition_id), replicaId=crate::apis::urlencode(p_path_replica_id));
    let mut req_builder = configuration.client.request(reqwest::Method::POST, &uri_str);

    req_builder = req_builder.query(&[("api-version", &p_query_api_version.to_string())]);
    req_builder = req_builder.query(&[("ServiceKind", &p_query_service_kind.to_string())]);
    if let Some(ref param_value) = p_query_immediate {
        req_builder = req_builder.query(&[("Immediate", &param_value.to_string())]);
    }
    if let Some(ref param_value) = p_query_timeout {
        req_builder = req_builder.query(&[("timeout", &param_value.to_string())]);
    }
    if let Some(ref user_agent) = configuration.user_agent {
        req_builder = req_builder.header(reqwest::header::USER_AGENT, user_agent.clone());
    }
    req_builder = req_builder.json(&p_body_health_information);

    let req = req_builder.build()?;
    let resp = configuration.client.execute(req).await?;

    let status = resp.status();

    if !status.is_client_error() && !status.is_server_error() {
        Ok(())
    } else {
        let content = resp.text().await?;
        let entity: Option<ReportReplicaHealthError> = serde_json::from_str(&content).ok();
        Err(Error::ResponseError(ResponseContent { status, content, entity }))
    }
}

